# List all files recursively in base directory up to depth 3
def list_files(root_dir, max_depth=3):
    results = []
    current_path = root_dir
    for d in range(max_depth):
        try:
            contents = os.listdir(current_path)
            for item in sorted(contents):
                path = os.path.join(current_path, item)
                results.append(path)
                if os.path.isdir(path):
                    results.extend(list_files(path, max_depth=d+1))
        except Exception as e:
            print(f"Error listing {current_path}: {e}")
    return results[:50]  # Limit output

